-- Imports the 80 proposed rows from PropertyPilot_Regular_Service_Catalogue_V1.xlsx.
-- Exact duplicate check against the prior catalog found one: Rental Property Management; it reuses PP_RENTAL_PROPERTY_MANAGEMENT.
-- Other entries get stable REG_* codes. New entries remain inactive and unpriced (0) until reviewed and configured by Admin.
-- Yes property types become eligibility rules; Conditional types are held for Admin review and are not customer-eligible.
ALTER TABLE services ADD COLUMN IF NOT EXISTS catalog_group VARCHAR(100);
ALTER TABLE services ADD COLUMN IF NOT EXISTS catalog_priority VARCHAR(20) NOT NULL DEFAULT 'CORE';
ALTER TABLE services ADD COLUMN IF NOT EXISTS delivery_policy VARCHAR(255);
ALTER TABLE services ADD COLUMN IF NOT EXISTS frequency VARCHAR(120);
ALTER TABLE services ADD COLUMN IF NOT EXISTS catalog_notes TEXT;
ALTER TABLE services ADD COLUMN IF NOT EXISTS conditional_property_types TEXT[] NOT NULL DEFAULT '{}'::text[];
CREATE TEMPORARY TABLE propertypilot_regular_service_catalog (service_code VARCHAR(80),service_name VARCHAR(255),category VARCHAR(100),catalog_group VARCHAR(100),catalog_priority VARCHAR(20),delivery_policy VARCHAR(255),frequency VARCHAR(120),catalog_notes TEXT,eligible_property_types TEXT[],conditional_property_types TEXT[],requires_visit BOOLEAN,visit_mandatory BOOLEAN,is_remote BOOLEAN) ON COMMIT DROP;
SELECT seed.service_code, seed.service_name, seed.category, 0, FALSE, seed.requires_visit, seed.visit_mandatory,
       CASE WHEN seed.requires_visit THEN 1 ELSE 0 END, seed.is_remote, seed.catalog_group, seed.catalog_priority,
       seed.delivery_policy, seed.frequency, seed.catalog_notes, seed.conditional_property_types
FROM propertypilot_regular_service_catalog seed
WHERE NOT EXISTS (
  SELECT 1 FROM services s
  WHERE lower(regexp_replace(s.service_name, '[^a-z0-9]', '', 'g'))=lower(regexp_replace(seed.service_name, '[^a-z0-9]', '', 'g'))
)
ON CONFLICT (service_code) DO NOTHING;
UPDATE services s
SET category=seed.category, catalog_group=seed.catalog_group, catalog_priority=seed.catalog_priority,
    delivery_policy=seed.delivery_policy, frequency=seed.frequency, catalog_notes=seed.catalog_notes,
    conditional_property_types=seed.conditional_property_types
FROM propertypilot_regular_service_catalog seed
WHERE lower(regexp_replace(s.service_name, '[^a-z0-9]', '', 'g'))=lower(regexp_replace(seed.service_name, '[^a-z0-9]', '', 'g'))
   OR s.service_code=seed.service_code;
SELECT gen_random_uuid(), s.service_id, 'PROPERTY_TYPE_COVERAGE',
       jsonb_build_object('field','PROPERTY_TYPE','operator','IN','value',to_jsonb(seed.eligible_property_types)), 100, 'ACTIVE'
FROM propertypilot_regular_service_catalog seed
JOIN services s ON lower(regexp_replace(s.service_name, '[^a-z0-9]', '', 'g'))=lower(regexp_replace(seed.service_name, '[^a-z0-9]', '', 'g'))
              OR s.service_code=seed.service_code
ON CONFLICT (service_id, rule_name) DO UPDATE
SET rule_definition=EXCLUDED.rule_definition, priority=EXCLUDED.priority, status='ACTIVE', updated_at=CURRENT_TIMESTAMP;
